import reactor.core.publisher.Mono;
import java.util.UUID;

public class EnrollmentService {
    private final EnrollmentRepository repository;

    public EnrollmentService(EnrollmentRepository repository) {
        this.repository = repository;
    }

    public Mono<Enrollment> findOwnedEnrollment(UUID id, UUID currentUserId) {
        // On filtre par id ET par propriétaire : un id d'un autre utilisateur
        // ne renvoie rien (Mono vide -> 404/403 côté web).
        return repository.findByIdAndUserId(id, currentUserId);
    }
}
